bicepPattern.managedIdentity:
resource managedIdentity 'Microsoft.ManagedIdentity/userAssignedIdentities@2023-01-31' = {
  name: managedIdentityName
  location: location
}

bicepPattern.appSettingsInjection:
Use siteConfig.appSettings array to inject all downstream service endpoints as env vars. Example:
appSettings: [
  { name: 'AZURE_CLIENT_ID', value: managedIdentity.properties.clientId }
  { name: 'AZURE_COSMOS_ENDPOINT', value: cosmosDb.outputs.cosmosEndpoint }
  { name: 'AZURE_REDIS_HOST', value: redis.outputs.redisHostName }
]

sdkInitPattern.typescript:
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential({
  managedIdentityClientId: process.env.AZURE_CLIENT_ID
});
